export function describeUser(user) {
  var label = user.name;
  if (user.role == 'admin') {
    label = label + ' (admin)';   
  }
  console.log('describeUser', label);
  return label;
}

export function initials(name) { var parts = String(name).split(' '); return parts.map(function (p) { return p.charAt(0).toUpperCase(); }).join(''); }

