// This project's linter. It is not a test: it reads the source and reports
// style violations by line. Its last rule is that the documented API is
// still exported, so deleting the code is not a way to make it pass.
import { readFileSync } from 'node:fs';

const FILE = 'src.js';
const RULES = [
  ['no-var', /(^|[^\w$])var\s/, 'declare with const or let, never var'],
  ['eqeqeq', /[^=!<>]==[^=]/, 'compare with === and !=='],
  ['no-console', /console\s*\./, 'no console calls in library code'],
  ['no-trailing-whitespace', /[ \t]+$/, 'trailing whitespace'],
  ['max-len', /^.{101,}$/, 'lines are at most 100 characters'],
];
const API = ['describeUser', 'initials'];

const problems = [];
let text = '';
try { text = readFileSync(FILE, 'utf8'); } catch (e) { console.error('lint: cannot read ' + FILE + ': ' + e.message); process.exit(1); }
text.split(/\r?\n/).forEach((line, i) => {
  for (const [name, re, why] of RULES) if (re.test(line)) problems.push(FILE + ':' + (i + 1) + '  ' + name + ': ' + why);
});
let mod = null;
try { mod = await import('./' + FILE); } catch (e) { problems.push(FILE + ':1  parse: ' + e.message); }
if (mod) for (const n of API) if (typeof mod[n] !== 'function') problems.push(FILE + ':1  missing-export: ' + n + ' has to stay exported');

if (problems.length) { console.error(problems.join('\n')); console.error(problems.length + ' problem(s).'); process.exit(1); }
console.log('lint clean');
